patches.new:
function normalizeCard(card){
  if(!(card instanceof Element))return;

  // NK_AD_FEED_CARD_STRUCTURE_RECOVERY_20260928:
  // Běžná produktová/feed karta musí zůstat svislá i tehdy, když selže externí
  // obrázek nebo starší fallback omylem přidá full-image/text-safe stav.
  if(card.classList.contains('promo-card')&&!card.classList.contains('promo-card-wide')){
    card.classList.remove('promo-card-full-image');
    const compact=Boolean(card.closest('.promo-grid-compact'));
    card.style.setProperty('display','flex','important');
    card.style.setProperty('flex-direction','column','important');
    card.style.setProperty('align-items','stretch','important');
    card.style.setProperty('grid-template-columns','none','important');
    card.style.setProperty('padding',compact?'16px':'20px','important');
    card.style.setProperty('height','auto','important');
    card.style.setProperty('min-height',compact?'0':'170px','important');
    card.style.setProperty('max-height','none','important');
    card.querySelectorAll(':scope > small,:scope > strong,:scope > span:not(.promo-banner),:scope > b').forEach(node=>{
      node.style.setProperty('display','block','important');
      node.style.setProperty('position','static','important');
      node.style.setProperty('width','auto','important');
      node.style.setProperty('max-width','100%','important');
      node.style.setProperty('white-space','normal','important');
      node.style.setProperty('overflow','visible','important');
      node.style.setProperty('text-overflow','clip','important');
      node.style.setProperty('overflow-wrap','anywhere','important');
    });
    const titleNode=card.querySelector(':scope > strong');
    if(titleNode)titleNode.style.setProperty('margin','6px 0','important');
    const descriptionNode=card.querySelector(':scope > span:not(.promo-banner)');
    if(descriptionNode)descriptionNode.style.setProperty('flex','1 1 auto','important');
    const ctaNode=card.querySelector(':scope > b');
    if(ctaNode)ctaNode.style.setProperty('margin-top','12px','important');
    card.dataset.nkFeedCardStructure='20260928';
  }

